// Loyalty promo lift analysis (WSC)
// Consumes SKU-level BigQuery rows and builds:
// - category / class / supplier / discount-bucket / baseline-tier summaries
// - markdown + HTML case study
// - Member Monday-template SVG charts for each summary bucket
// - Google Sheets payloads

const rows = $input.all().map((item) => item.json);
const configureInputs = (() => {
  try {
    return $('Configure Inputs').first().json || {};
  } catch (error) {
    return {};
  }
})();

function toNumber(value) {
  if (value === null || value === undefined || value === '') return 0;
  if (typeof value === 'number') return value;
  const cleaned = String(value).replace(/[$,%]/g, '').trim();
  const num = Number(cleaned);
  return Number.isFinite(num) ? num : 0;
}

function round(value, digits = 2) {
  const factor = 10 ** digits;
  return Math.round((Number(value) + Number.EPSILON) * factor) / factor;
}

function fmtCurrency(value) {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(toNumber(value));
}

function fmtPct(value, digits = 1) {
  if (value === null || value === undefined || Number.isNaN(Number(value))) return 'n/a';
  return `${(toNumber(value) * 100).toFixed(digits)}%`;
}

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function discountBucket(discountPct) {
  const d = toNumber(discountPct);
  if (d < 0.1) return '<10%';
  if (d < 0.15) return '10-14.9%';
  if (d < 0.2) return '15-19.9%';
  if (d < 0.25) return '20-24.9%';
  return '25%+';
}

function quantile(sortedValues, q) {
  if (!sortedValues.length) return 0;
  const pos = (sortedValues.length - 1) * q;
  const base = Math.floor(pos);
  const rest = pos - base;
  if (sortedValues[base + 1] === undefined) return sortedValues[base];
  return sortedValues[base] + rest * (sortedValues[base + 1] - sortedValues[base]);
}

function weightedAvg(values, weights) {
  let num = 0;
  let den = 0;
  for (let i = 0; i < values.length; i += 1) {
    const value = values[i];
    const weight = weights[i];
    if (value === null || value === undefined || Number.isNaN(value)) continue;
    if (!weight || weight <= 0) continue;
    num += value * weight;
    den += weight;
  }
  if (den > 0) return num / den;
  const valid = values.filter((v) => v !== null && v !== undefined && !Number.isNaN(v));
  if (!valid.length) return null;
  return valid.reduce((a, b) => a + b, 0) / valid.length;
}

function summarize(records, groupKeyFn) {
  const groups = new Map();
  for (const row of records) {
    const keyObj = groupKeyFn(row);
    const key = JSON.stringify(keyObj);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(row);
  }

  const summaries = [];
  for (const [key, group] of groups.entries()) {
    const keyObj = JSON.parse(key);
    const baseline = group.reduce((sum, row) => sum + row.non_promo_avg, 0);
    const loyalty = group.reduce((sum, row) => sum + row.loyalty_avg, 0);
    const incremental = loyalty - baseline;
    const weightedLift = baseline ? incremental / baseline : null;
    const skuCount = new Set(group.map((row) => row.sku)).size;
    const activeSkus = new Set(group.filter((row) => row.loyalty_avg > 0).map((row) => row.sku)).size;
    const positiveSkus = new Set(group.filter((row) => row.incremental_wsc > 0).map((row) => row.sku)).size;
    const weightedDiscount = weightedAvg(
      group.map((row) => row.discount_pct),
      group.map((row) => row.non_promo_avg),
    );

    summaries.push({
      ...keyObj,
      sku_count: skuCount,
      active_skus: activeSkus,
      positive_lift_skus: positiveSkus,
      positive_lift_sku_rate: skuCount ? positiveSkus / skuCount : null,
      non_promo_avg: round(baseline, 2),
      loyalty_avg: round(loyalty, 2),
      incremental_wsc: round(incremental, 2),
      weighted_lift_pct: weightedLift === null ? null : round(weightedLift, 4),
      weighted_discount_pct: weightedDiscount === null ? null : round(weightedDiscount, 4),
    });
  }

  return summaries.sort((a, b) => b.loyalty_avg - a.loyalty_avg || b.incremental_wsc - a.incremental_wsc);
}

function markdownTable(tableRows, columns) {
  if (!tableRows.length) return '_No rows_';
  const body = tableRows.map((row) =>
    columns.map((col) => {
      const value = row[col];
      if (value === null || value === undefined) return '';
      return String(value);
    }),
  );
  const widths = columns.map((header, idx) =>
    Math.max(header.length, ...body.map((row) => row[idx].length)),
  );
  const render = (values) =>
    `| ${values.map((value, idx) => value.padEnd(widths[idx])).join(' | ')} |`;
  return [
    render(columns),
    `| ${widths.map((width) => '-'.repeat(width)).join(' | ')} |`,
    ...body.map(render),
  ].join('\n');
}

function htmlTable(tableRows, columns) {
  if (!tableRows.length) return '<p><em>No rows</em></p>';
  const head = columns
    .map(
      (col) =>
        `<th style="text-align:left;padding:6px 10px;border-bottom:1px solid #ddd;">${escapeHtml(col)}</th>`,
    )
    .join('');
  const body = tableRows
    .map((row) => {
      const cells = columns
        .map(
          (col) =>
            `<td style="padding:6px 10px;border-bottom:1px solid #f0f0f0;">${escapeHtml(row[col] ?? '')}</td>`,
        )
        .join('');
      return `<tr>${cells}</tr>`;
    })
    .join('');
  return `<table style="border-collapse:collapse;width:100%;font-size:13px;"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table>`;
}

function formatSummaryRows(tableRows) {
  return tableRows.map((row) => ({
    ...row,
    positive_lift_sku_rate: fmtPct(row.positive_lift_sku_rate),
    weighted_discount_pct: fmtPct(row.weighted_discount_pct),
    non_promo_avg: fmtCurrency(row.non_promo_avg),
    loyalty_avg: fmtCurrency(row.loyalty_avg),
    incremental_wsc: fmtCurrency(row.incremental_wsc),
    weighted_lift_pct: fmtPct(row.weighted_lift_pct),
  }));
}


function fmtPctLabel(value, digits = 1) {
  if (value === null || value === undefined || Number.isNaN(Number(value))) return 'n/a';
  return `${(toNumber(value) * 100).toFixed(digits)}%`;
}

function fmtShortCurrency(value) {
  const num = toNumber(value);
  const abs = Math.abs(num);
  if (abs >= 1000000) return `$${(num / 1000000).toFixed(1)}M`;
  if (abs >= 1000) return `$${(num / 1000).toFixed(abs >= 10000 ? 0 : 1)}K`;
  return `$${Math.round(num).toLocaleString('en-US')}`;
}

function truncateLabel(name, maxLen = 32) {
  const text = String(name || '');
  if (text.length <= maxLen) return text;
  return `${text.slice(0, Math.max(1, maxLen - 1))}…`;
}

function abbreviateLabel(name, maxLen = 18) {
  const clean = String(name || '').replace(/[^A-Za-z0-9 &]/g, '').trim();
  const words = clean.split(/\s+/).filter((w) => !['inc', 'llc', 'ltd', 'co', 'corp', '&'].includes(w.toLowerCase()));
  if (!words.length) return truncateLabel(name, maxLen);
  let candidate = words.slice(0, 2).join(' ');
  if (candidate.length > maxLen) candidate = words[0].slice(0, maxLen);
  return candidate;
}

function svgEscape(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function chartWrap(title, svg) {
  const encoded = Buffer.from(svg, 'utf8').toString('base64');
  const img = `<img alt="${escapeHtml(title)}" src="data:image/svg+xml;base64,${encoded}" style="max-width:100%;height:auto;border:1px solid #eee;background:#fff;display:block;" />`;
  return `<div style="margin:18px 0 8px 0;"><div style="font-weight:600;margin-bottom:6px;">${escapeHtml(title)}</div>${img}</div>`;
}

/** Template: Member Monday class chart — horizontal grouped bars (L10 grey vs loyalty blue). */
function svgGroupedHorizontalBars(rows, labelKey, title, baselineLabel, loyaltyLabel) {
  if (!rows.length) return '';
  const width = 860;
  const rowH = 46;
  const margin = { top: 36, right: 90, bottom: 40, left: 190 };
  const height = margin.top + margin.bottom + rows.length * rowH;
  const plotW = width - margin.left - margin.right;
  const maxVal = Math.max(
    1,
    ...rows.map((r) => Math.max(toNumber(r.non_promo_avg), toNumber(r.loyalty_avg))),
  );
  const y0 = margin.top;
  let bars = '';
  rows.forEach((row, idx) => {
    const y = y0 + idx * rowH;
    const baseline = toNumber(row.non_promo_avg);
    const loyalty = toNumber(row.loyalty_avg);
    const w1 = (baseline / maxVal) * plotW;
    const w2 = (loyalty / maxVal) * plotW;
    const label = truncateLabel(row[labelKey], 28);
    bars += `<text x="${margin.left - 10}" y="${y + 22}" text-anchor="end" font-size="12" fill="#222">${svgEscape(label)}</text>`;
    bars += `<rect x="${margin.left}" y="${y + 6}" width="${w1}" height="14" fill="#9aa6b2" rx="2"/>`;
    bars += `<rect x="${margin.left}" y="${y + 24}" width="${w2}" height="14" fill="#2f6fed" rx="2"/>`;
    bars += `<text x="${margin.left + Math.max(w1, w2) + 8}" y="${y + 35}" font-size="11" fill="#222">${svgEscape(fmtPctLabel(row.weighted_lift_pct))}</text>`;
  });
  const ticks = 5;
  let axis = '';
  for (let i = 0; i <= ticks; i += 1) {
    const val = (maxVal * i) / ticks;
    const x = margin.left + (plotW * i) / ticks;
    axis += `<line x1="${x}" y1="${margin.top}" x2="${x}" y2="${height - margin.bottom}" stroke="#e6e8eb"/>`;
    axis += `<text x="${x}" y="${height - margin.bottom + 18}" text-anchor="middle" font-size="11" fill="#59636e">${svgEscape(fmtShortCurrency(val))}</text>`;
  }
  const legend = `
    <rect x="${width - 290}" y="8" width="14" height="10" fill="#9aa6b2"/><text x="${width - 272}" y="17" font-size="11" fill="#222">${svgEscape(baselineLabel)}</text>
    <rect x="${width - 150}" y="8" width="14" height="10" fill="#2f6fed"/><text x="${width - 132}" y="17" font-size="11" fill="#222">${svgEscape(loyaltyLabel)}</text>
  `;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${svgEscape(title)}" style="max-width:100%;height:auto;background:#fff;border:1px solid #eee;">
    <text x="${margin.left}" y="22" font-size="14" font-weight="600" fill="#222">${svgEscape(title)}</text>
    ${legend}${axis}${bars}
    <text x="${margin.left + plotW / 2}" y="${height - 6}" text-anchor="middle" font-size="11" fill="#59636e">WSC dollars</text>
  </svg>`;
  return chartWrap(title, svg);
}

/** Template: Member Monday discount-investment lift bars. */
function svgLiftBars(rows, labelKey, title, colors) {
  if (!rows.length) return '';
  const width = 760;
  const height = 360;
  const margin = { top: 40, right: 24, bottom: 70, left: 70 };
  const plotW = width - margin.left - margin.right;
  const plotH = height - margin.top - margin.bottom;
  const values = rows.map((r) => toNumber(r.weighted_lift_pct) * 100);
  const maxAbs = Math.max(20, ...values.map((v) => Math.abs(v)));
  const yMax = maxAbs;
  const yMin = Math.min(0, Math.min(...values, 0));
  const span = yMax - yMin || 1;
  const barW = Math.min(70, (plotW / rows.length) * 0.62);
  const zeroY = margin.top + ((yMax - 0) / span) * plotH;
  let bars = '';
  rows.forEach((row, idx) => {
    const lift = toNumber(row.weighted_lift_pct) * 100;
    const x = margin.left + ((idx + 0.5) * plotW) / rows.length - barW / 2;
    const y = margin.top + ((yMax - Math.max(lift, 0)) / span) * plotH;
    const h = Math.abs((lift / span) * plotH);
    const color = Array.isArray(colors) ? colors[idx % colors.length] : colors || '#4b347f';
    bars += `<rect x="${x}" y="${lift >= 0 ? y : zeroY}" width="${barW}" height="${Math.max(h, 1)}" fill="${color}" rx="3"/>`;
    bars += `<text x="${x + barW / 2}" y="${lift >= 0 ? y - 8 : zeroY + h + 14}" text-anchor="middle" font-size="12" fill="#222">${svgEscape(fmtPctLabel(row.weighted_lift_pct, 0))}</text>`;
    bars += `<text x="${x + barW / 2}" y="${height - margin.bottom + 22}" text-anchor="middle" font-size="11" fill="#222">${svgEscape(String(row[labelKey]))}</text>`;
  });
  let grid = `<line x1="${margin.left}" y1="${zeroY}" x2="${width - margin.right}" y2="${zeroY}" stroke="#59636e" stroke-width="1.2"/>`;
  for (let i = 0; i <= 4; i += 1) {
    const val = yMin + (span * i) / 4;
    const y = margin.top + ((yMax - val) / span) * plotH;
    grid += `<line x1="${margin.left}" y1="${y}" x2="${width - margin.right}" y2="${y}" stroke="#eef0f3"/>`;
    grid += `<text x="${margin.left - 8}" y="${y + 4}" text-anchor="end" font-size="11" fill="#59636e">${Math.round(val)}%</text>`;
  }
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${svgEscape(title)}" style="max-width:100%;height:auto;background:#fff;border:1px solid #eee;">
    <text x="${margin.left}" y="24" font-size="14" font-weight="600" fill="#222">${svgEscape(title)}</text>
    ${grid}${bars}
    <text x="${margin.left + plotW / 2}" y="${height - 10}" text-anchor="middle" font-size="11" fill="#59636e">${svgEscape(String(labelKey).split('_').join(' '))}</text>
    <text x="18" y="${margin.top + plotH / 2}" text-anchor="middle" font-size="11" fill="#59636e" transform="rotate(-90 18 ${margin.top + plotH / 2})">Weighted lift %</text>
  </svg>`;
  return chartWrap(title, svg);
}

/** Template: Member Monday grouped vertical bars (purple) for bucket sales comparison. */
function svgGroupedVerticalBars(rows, labelKey, title, baselineLabel, loyaltyLabel) {
  if (!rows.length) return '';
  const width = 820;
  const height = 380;
  const margin = { top: 50, right: 20, bottom: 80, left: 70 };
  const plotW = width - margin.left - margin.right;
  const plotH = height - margin.top - margin.bottom;
  const maxVal = Math.max(1, ...rows.map((r) => Math.max(toNumber(r.non_promo_avg), toNumber(r.loyalty_avg))));
  const groupW = plotW / rows.length;
  const barW = Math.min(34, groupW * 0.32);
  let bars = '';
  rows.forEach((row, idx) => {
    const cx = margin.left + (idx + 0.5) * groupW;
    const b = toNumber(row.non_promo_avg);
    const l = toNumber(row.loyalty_avg);
    const h1 = (b / maxVal) * plotH;
    const h2 = (l / maxVal) * plotH;
    bars += `<rect x="${cx - barW - 2}" y="${margin.top + plotH - h1}" width="${barW}" height="${h1}" fill="#9b7ce3" rx="2"/>`;
    bars += `<rect x="${cx + 2}" y="${margin.top + plotH - h2}" width="${barW}" height="${h2}" fill="#4b347f" rx="2"/>`;
    bars += `<text x="${cx}" y="${margin.top + plotH - Math.max(h1, h2) - 8}" text-anchor="middle" font-size="11" fill="#222">${svgEscape(fmtPctLabel(row.weighted_lift_pct))}</text>`;
    bars += `<text x="${cx}" y="${height - margin.bottom + 28}" text-anchor="middle" font-size="11" fill="#222">${svgEscape(String(row[labelKey]))}</text>`;
  });
  let grid = '';
  for (let i = 0; i <= 4; i += 1) {
    const val = (maxVal * i) / 4;
    const y = margin.top + plotH - (plotH * i) / 4;
    grid += `<line x1="${margin.left}" y1="${y}" x2="${width - margin.right}" y2="${y}" stroke="#eef0f3"/>`;
    grid += `<text x="${margin.left - 8}" y="${y + 4}" text-anchor="end" font-size="11" fill="#59636e">${svgEscape(fmtShortCurrency(val))}</text>`;
  }
  const legend = `
    <rect x="${margin.left}" y="10" width="12" height="10" fill="#9b7ce3"/><text x="${margin.left + 18}" y="19" font-size="11" fill="#222">${svgEscape(baselineLabel)}</text>
    <rect x="${margin.left + 170}" y="10" width="12" height="10" fill="#4b347f"/><text x="${margin.left + 188}" y="19" font-size="11" fill="#222">${svgEscape(loyaltyLabel)}</text>
  `;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${svgEscape(title)}" style="max-width:100%;height:auto;background:#fff;border:1px solid #eee;">
    <text x="${margin.left}" y="38" font-size="14" font-weight="600" fill="#222">${svgEscape(title)}</text>
    ${legend}${grid}${bars}
  </svg>`;
  return chartWrap(title, svg);
}

/** Template: Supplier lift vs promotional investment (green/red bars at discount %). */
function svgSupplierLiftVsInvestment(rows, title) {
  const plotRows = rows
    .filter((r) => (toNumber(r.non_promo_avg) > 0 || toNumber(r.loyalty_avg) > 0)
      && r.weighted_discount_pct !== null && r.weighted_lift_pct !== null)
    .sort((a, b) => b.loyalty_avg - a.loyalty_avg)
    .slice(0, 14)
    .map((r) => ({
      ...r,
      liftPct: toNumber(r.weighted_lift_pct) * 100,
      discountPct: toNumber(r.weighted_discount_pct) * 100,
      displayLift: Math.max(-110, Math.min(100, toNumber(r.weighted_lift_pct) * 100)),
      displayName: abbreviateLabel(r.supplier_name, 13),
    }));
  if (!plotRows.length) return '';

  // nudge overlapping discount positions
  const clusters = new Map();
  plotRows.forEach((r, idx) => {
    const key = Math.round(r.discountPct);
    if (!clusters.has(key)) clusters.set(key, []);
    clusters.get(key).push(idx);
  });
  const xPlot = plotRows.map((r) => r.discountPct);
  clusters.forEach((idxs) => {
    if (idxs.length === 1) return;
    idxs.forEach((idx, i) => {
      xPlot[idx] = plotRows[idx].discountPct + (i - (idxs.length - 1) / 2) * 1.2;
    });
  });

  const width = 860;
  const height = 420;
  const margin = { top: 36, right: 24, bottom: 50, left: 60 };
  const plotW = width - margin.left - margin.right;
  const plotH = height - margin.top - margin.bottom;
  const xMin = Math.max(0, Math.min(...plotRows.map((r) => r.discountPct)) - 3);
  const xMax = Math.max(...plotRows.map((r) => r.discountPct)) + 4;
  const yMin = Math.min(-20, ...plotRows.map((r) => r.displayLift - 20));
  const yMax = Math.max(60, ...plotRows.map((r) => r.displayLift + 30));
  const xScale = (v) => margin.left + ((v - xMin) / (xMax - xMin || 1)) * plotW;
  const yScale = (v) => margin.top + ((yMax - v) / (yMax - yMin || 1)) * plotH;
  const zeroY = yScale(0);
  const barW = Math.max(10, plotW / 70);
  let bars = '';
  plotRows.forEach((row, idx) => {
    const x = xScale(xPlot[idx]) - barW / 2;
    const y = yScale(Math.max(row.displayLift, 0));
    const h = Math.abs(yScale(row.displayLift) - zeroY);
    const color = row.incremental_wsc > 0 ? '#16a163' : row.incremental_wsc < 0 ? '#c84c4c' : '#9aa6b2';
    bars += `<rect x="${x}" y="${row.displayLift >= 0 ? y : zeroY}" width="${barW}" height="${Math.max(h, 1)}" fill="${color}" fill-opacity="0.85" stroke="#fff" stroke-width="0.7"/>`;
    const labelY = row.displayLift >= 0 ? y - 8 : zeroY + h + 12;
    bars += `<text x="${x + barW / 2}" y="${labelY}" text-anchor="middle" font-size="10" fill="#0b1f44">${svgEscape(row.displayName)}</text>`;
    bars += `<text x="${x + barW / 2}" y="${labelY + 12}" text-anchor="middle" font-size="10" fill="#0b1f44">${svgEscape(`${Math.round(row.liftPct).toLocaleString('en-US')}%`)}</text>`;
  });
  let grid = `<line x1="${margin.left}" y1="${zeroY}" x2="${width - margin.right}" y2="${zeroY}" stroke="#59636e"/>`;
  for (let i = 0; i <= 4; i += 1) {
    const xv = xMin + ((xMax - xMin) * i) / 4;
    const yv = yMin + ((yMax - yMin) * i) / 4;
    const x = xScale(xv);
    const y = yScale(yv);
    grid += `<line x1="${x}" y1="${margin.top}" x2="${x}" y2="${height - margin.bottom}" stroke="#eef0f3"/>`;
    grid += `<line x1="${margin.left}" y1="${y}" x2="${width - margin.right}" y2="${y}" stroke="#eef0f3"/>`;
    grid += `<text x="${x}" y="${height - margin.bottom + 18}" text-anchor="middle" font-size="11" fill="#59636e">${Math.round(xv)}%</text>`;
    grid += `<text x="${margin.left - 8}" y="${y + 4}" text-anchor="end" font-size="11" fill="#59636e">${Math.round(yv)}%</text>`;
  }
  const capped = plotRows.some((r) => r.liftPct !== r.displayLift);
  const note = capped
    ? `<text x="${width - margin.right}" y="${height - 8}" text-anchor="end" font-size="10" fill="#59636e">Bars capped at -110% and 100% for readability; labels show actual lift</text>`
    : '';
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${svgEscape(title)}" style="max-width:100%;height:auto;background:#fff;border:1px solid #eee;">
    <text x="${margin.left}" y="22" font-size="14" font-weight="600" fill="#222">${svgEscape(title)}</text>
    ${grid}${bars}${note}
    <text x="${margin.left + plotW / 2}" y="${height - 22}" text-anchor="middle" font-size="11" fill="#59636e">Weighted discount %</text>
    <text x="16" y="${margin.top + plotH / 2}" text-anchor="middle" font-size="11" fill="#59636e" transform="rotate(-90 16 ${margin.top + plotH / 2})">Weighted lift %</text>
  </svg>`;
  return chartWrap(title, svg);
}

/** Template: top incremental supplier success stories. */
function svgTopIncremental(rows, title) {
  const plotRows = rows
    .filter((r) => toNumber(r.incremental_wsc) > 0)
    .sort((a, b) => a.incremental_wsc - b.incremental_wsc)
    .slice(-10);
  if (!plotRows.length) return '';
  const width = 820;
  const rowH = 34;
  const margin = { top: 36, right: 80, bottom: 36, left: 220 };
  const height = margin.top + margin.bottom + plotRows.length * rowH;
  const plotW = width - margin.left - margin.right;
  const maxVal = Math.max(1, ...plotRows.map((r) => toNumber(r.incremental_wsc)));
  let bars = '';
  plotRows.forEach((row, idx) => {
    const y = margin.top + idx * rowH;
    const w = (toNumber(row.incremental_wsc) / maxVal) * plotW;
    bars += `<text x="${margin.left - 10}" y="${y + 18}" text-anchor="end" font-size="12" fill="#222">${svgEscape(row.supplier_name)}</text>`;
    bars += `<rect x="${margin.left}" y="${y + 6}" width="${w}" height="18" fill="#16a163" rx="2"/>`;
    bars += `<text x="${margin.left + w + 8}" y="${y + 19}" font-size="11" fill="#222">${svgEscape(fmtCurrency(row.incremental_wsc))}</text>`;
  });
  let axis = '';
  for (let i = 0; i <= 4; i += 1) {
    const val = (maxVal * i) / 4;
    const x = margin.left + (plotW * i) / 4;
    axis += `<line x1="${x}" y1="${margin.top}" x2="${x}" y2="${height - margin.bottom}" stroke="#eef0f3"/>`;
    axis += `<text x="${x}" y="${height - 10}" text-anchor="middle" font-size="11" fill="#59636e">${svgEscape(fmtShortCurrency(val))}</text>`;
  }
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${svgEscape(title)}" style="max-width:100%;height:auto;background:#fff;border:1px solid #eee;">
    <text x="${margin.left}" y="22" font-size="14" font-weight="600" fill="#222">${svgEscape(title)}</text>
    ${axis}${bars}
    <text x="${margin.left + plotW / 2}" y="${height - 22}" text-anchor="middle" font-size="11" fill="#59636e">Incremental loyalty WSC dollars</text>
  </svg>`;
  return chartWrap(title, svg);
}


